import React from 'react';
import { MapContainer, TileLayer, Marker, Popup, Polygon } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';

// Sample GeoJSON-like data for demo
const farms = [
  {
    id: 'FARM-001',
    name: 'Kitale Central',
    position: [1.015, 35.006],
    risk: 'High',
    health: 'Moderate Stress',
    action: 'Scout for FAW, apply biopesticide',
    zone: [[1.01, 35.00], [1.02, 35.00], [1.02, 35.01], [1.01, 35.01]]
  },
  {
    id: 'FARM-002',
    name: 'Kiminini',
    position: [0.966, 34.991],
    risk: 'Low',
    health: 'Healthy',
    action: 'Continue monitoring',
    zone: [[0.965, 34.99], [0.967, 34.99], [0.967, 34.992], [0.965, 34.992]]
  },
  {
    id: 'FARM-003',
    name: 'Endebess',
    position: [1.080, 34.850],
    risk: 'Very High',
    health: 'Severe Stress',
    action: 'Alert extension officer, scout daily',
    zone: [[1.079, 34.849], [1.081, 34.849], [1.081, 34.851], [1.079, 34.851]]
  }
];

const riskColors = {
  'Low': 'green',
  'Medium': 'orange',
  'High': 'red',
  'Very High': 'purple'
};

const InteractiveMap = () => (
  <div className="w-full h-96 rounded-lg overflow-hidden">
    <MapContainer center={[1.015, 35.006]} zoom={10} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        attribution='&copy; OpenStreetMap contributors'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />
      {farms.map(farm => (
        <>
          <Marker key={farm.id} position={farm.position}>
            <Popup>
              <strong>{farm.name}</strong><br />
              Pest Risk: <span className={`text-${riskColors[farm.risk] || 'gray'}-600`}>{farm.risk}</span><br />
              Crop Health: {farm.health}<br />
              Action: {farm.action}
            </Popup>
          </Marker>
          <Polygon key={farm.id + '-zone'} positions={farm.zone} pathOptions={{ color: riskColors[farm.risk] || 'gray', fillOpacity: 0.3 }} />
        </>
      ))}
    </MapContainer>
  </div>
);

export default InteractiveMap;
